CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, phone text, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('owner','staff','member')), must_change_password boolean NOT NULL DEFAULT false, member_id text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS members (id text PRIMARY KEY, member_code text NOT NULL UNIQUE, name text NOT NULL, email text NOT NULL UNIQUE, phone text NOT NULL, source text NOT NULL, qr_token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS plans (id text PRIMARY KEY, name text NOT NULL UNIQUE, duration_months integer NOT NULL CHECK(duration_months IN (1,3,12)), price_cents integer NOT NULL CHECK(price_cents > 0), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS memberships (id text PRIMARY KEY, member_id text NOT NULL REFERENCES members(id), plan_id text NOT NULL REFERENCES plans(id), starts_at date NOT NULL, expires_at date NOT NULL, price_cents integer NOT NULL CHECK(price_cents > 0), renewal_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE memberships ADD COLUMN IF NOT EXISTS renewal_key text;
CREATE UNIQUE INDEX IF NOT EXISTS memberships_renewal_key_unique ON memberships(renewal_key);
CREATE INDEX IF NOT EXISTS memberships_member_idx ON memberships(member_id);
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY, member_id text NOT NULL REFERENCES members(id), membership_id text NOT NULL REFERENCES memberships(id), amount_cents integer NOT NULL CHECK(amount_cents > 0), method text NOT NULL CHECK(method IN ('cash','gcash','bank_transfer')), reference text, paid_at timestamptz NOT NULL DEFAULT now(), recorded_by text NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS attendance (id text PRIMARY KEY, member_id text NOT NULL REFERENCES members(id), checked_in_at timestamptz NOT NULL DEFAULT now(), manila_date date NOT NULL, method text NOT NULL CHECK(method IN ('qr','manual')), UNIQUE(member_id,manila_date));
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits (key text PRIMARY KEY, attempts integer NOT NULL, window_started_at timestamptz NOT NULL, blocked_until timestamptz);
CREATE TABLE IF NOT EXISTS audit_log (id text PRIMARY KEY, actor_id text NOT NULL, action text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
